CREATE TABLE crm.pipeline_definition (
 id UUID PRIMARY KEY,organization_id UUID NOT NULL REFERENCES crm.organization(id),name VARCHAR(200) NOT NULL,
 stages JSONB NOT NULL CHECK(jsonb_typeof(stages)='array'),created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,archived BOOLEAN NOT NULL DEFAULT false,
 UNIQUE(organization_id,id)
);
CREATE UNIQUE INDEX uq_pipeline_active_name ON crm.pipeline_definition(organization_id,lower(name)) WHERE archived=false;
ALTER TABLE crm.opportunity ADD COLUMN pipeline_id UUID;
ALTER TABLE crm.opportunity ADD COLUMN pipeline_stage_key VARCHAR(50);
ALTER TABLE crm.opportunity ADD CONSTRAINT ck_opportunity_pipeline_pair CHECK((pipeline_id IS NULL)=(pipeline_stage_key IS NULL));
ALTER TABLE crm.opportunity ADD CONSTRAINT fk_opportunity_pipeline_organization FOREIGN KEY(organization_id,pipeline_id) REFERENCES crm.pipeline_definition(organization_id,id);
CREATE INDEX idx_opportunity_pipeline ON crm.opportunity(organization_id,pipeline_id,pipeline_stage_key) WHERE archived=false;
ALTER TABLE crm.audit_event DROP CONSTRAINT audit_event_event_type_check;
ALTER TABLE crm.audit_event ADD CONSTRAINT audit_event_event_type_check CHECK(event_type IN (
 'COMPANY_CREATED','COMPANY_UPDATED','COMPANY_ARCHIVED','CONTACT_CREATED','CONTACT_UPDATED','CONTACT_ARCHIVED',
 'LEAD_CREATED','LEAD_UPDATED','LEAD_STATUS_CHANGED','LEAD_ARCHIVED','OPPORTUNITY_CREATED','OPPORTUNITY_UPDATED','OPPORTUNITY_STAGE_CHANGED','OPPORTUNITY_ARCHIVED',
 'ACTIVITY_CREATED','ACTIVITY_UPDATED','ACTIVITY_ARCHIVED','TASK_CREATED','TASK_UPDATED','TASK_STATUS_CHANGED','TASK_ARCHIVED',
 'NOTE_CREATED','NOTE_UPDATED','NOTE_ARCHIVED','SAVED_VIEW_CREATED','SAVED_VIEW_UPDATED','SAVED_VIEW_ARCHIVED',
 'ORGANIZATION_CREATED','ORGANIZATION_UPDATED','ORGANIZATION_ARCHIVED','MEMBERSHIP_CREATED','MEMBERSHIP_STATUS_CHANGED','MEMBERSHIP_ROLE_CHANGED',
 'ORGANIZATION_OWNERSHIP_TRANSFERRED','USER_ACTIVATION_CHANGED','USER_PROFILE_UPDATED','LOGIN_SUCCEEDED','LOGIN_FAILED','LOGOUT_SUCCEEDED','ACCESS_DENIED',
 'DATA_IMPORT_PREVIEWED','DATA_IMPORT_SUCCEEDED','DATA_IMPORT_FAILED','DATA_EXPORT_SUCCEEDED','DATA_EXPORT_FAILED','PIPELINE_CREATED','PIPELINE_UPDATED','PIPELINE_ARCHIVED'
));
ALTER TABLE crm.audit_event DROP CONSTRAINT audit_event_target_type_check;
ALTER TABLE crm.audit_event ADD CONSTRAINT audit_event_target_type_check CHECK(target_type IN ('COMPANY','CONTACT','LEAD','OPPORTUNITY','ACTIVITY','TASK','NOTE','SAVED_VIEW','ORGANIZATION','ORGANIZATION_MEMBERSHIP','USER','API_REQUEST','DATA_TRANSFER','PIPELINE'));
